// Idempotence guard: if the engine is already running in-memory and was
// transitioned recently (last 60s), don't clobber it from disk. Protects
// against a /start call landing between flow-deploy and this bootstrap.
const existing = global.get('engine');
if (existing && existing.state === 'running'
    && (Date.now() - (existing.last_transition_at || 0)) < 60000) {
    node.log('engine already running (in-memory, transition <60s old); skipping restore');
    return null;
}

function defaultEngine() {
    return {
        state: 'initialized',
        simulation_time: new Date().toISOString(),
        seed: Number(env.get('BASE_SEED') || 12345),
        acceleration: Number(env.get('SPEED_FACTOR') || 1),
        registered_entities: 0,
        last_transition_at: Date.now()
    };
}
// On startup, parse the persisted state.json (if any) into flow context.
let engine;
try {
    if (msg.payload && typeof msg.payload === 'object' && msg.payload.state) {
        engine = msg.payload;
    } else if (typeof msg.payload === 'string' && msg.payload.length > 0) {
        engine = JSON.parse(msg.payload);
    } else {
        engine = defaultEngine();
    }
} catch (err) {
    node.warn('Failed to parse persisted engine state, using defaults: ' + err.message);
    engine = defaultEngine();
}
global.set('engine', engine);
node.log('Engine state loaded: ' + engine.state + ' @ ' + engine.simulation_time);
return null;

// Idempotence guard: never overwrite an already-set engine. The restore
